const ll INF = LLONG_MAX / 3;
using P = pair<ll, int>;
const int N = 4004;
struct SegTree {
  int n;
  vector<P> dat;
  SegTree(int _n) {
    n = 1;
    while (n < _n) n *= 2;
    dat = vector<P>(2 * n - 1, {INF, N});
  }
  void update_min(int k, ll a, int idx) {
    k += n - 1;
    dat[k] = min(dat[k], {a, idx});
    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
    }
  }
  P _query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return {INF, N};
    if (a <= l && r <= b) return dat[k];
    P vl = _query(a, b, 2 * k + 1, l, (l + r) / 2);
    P vr = _query(a, b, 2 * k + 2, (l + r) / 2, r);
    return min(vl, vr);
  }
  P query(int a, int b) { return _query(a, b, 0, 0, n); }
};
ll dp[N][N];
int par[N][N];
int main() {
  int n;
  scanf(" %d", &n);
  vector<ll> a(n);
  for (int(i) = 0; (i) < (int)(n); ++(i)) scanf(" %lld", &a[i]);
  vector<ll> s(n + 1);
  for (int i = 1; i <= n; ++i) s[i] = s[i - 1] + a[i - 1];
  fill(dp[0], dp[N], INF);
  dp[0][0] = -INF;
  fill(par[0], par[N], -1);
  for (int i = 1; i <= n; ++i) {
    vector<ll> v;
    for (int(j) = 0; (j) < (int)(n + 1); ++(j)) {
      v.push_back(s[j] + dp[i - 1][j]);
    }
    sort((v).begin(), (v).end());
    v.erase(unique((v).begin(), (v).end()), v.end());
    int V = v.size();
    SegTree st(V);
    for (int(j) = 0; (j) < (int)(n + 1); ++(j)) {
      int idx = lower_bound((v).begin(), (v).end(), s[j]) - v.begin();
      P res = st.query(0, idx);
      if (dp[i][j] > s[j] + res.first) {
        dp[i][j] = s[j] + res.first;
        par[i][j] = res.second;
      }
      int uidx =
          lower_bound((v).begin(), (v).end(), s[j] + dp[i - 1][j]) - v.begin();
      st.update_min(uidx, -s[j], j);
    }
  }
  int m = 0;
  for (int(i) = 0; (i) < (int)(n + 1); ++(i)) {
    if (dp[i][n] < INF) m = i;
  }
  int now = n;
  vector<int> ans;
  for (int(i) = 0; (i) < (int)(m - 1); ++(i)) {
    now = par[m - i][now];
    ans.push_back(now);
  }
  reverse((ans).begin(), (ans).end());
  printf("%d\n", m);
  for (int(i) = 0; (i) < (int)(m - 1); ++(i))
    printf("%d%c", ans[i], " \n"[i == m - 2]);
  return 0;
}

