#include <bits/stdc++.h>
using namespace std;
void merge_sort_count_inversion(vector<int>& a, int left, int right, int level,
                                vector<long long int>& total_inversions,
                                vector<int>& tmp) {
  if (left == right) {
    return;
  }
  int mid = (left + right) / 2;
  merge_sort_count_inversion(a, left, mid, level - 1, total_inversions, tmp);
  merge_sort_count_inversion(a, mid + 1, right, level - 1, total_inversions,
                             tmp);
  for (int i = left; i <= right; i++) {
    tmp[i] = a[i];
  }
  int aptr = left;
  int leftptr = left;
  int rightptr = mid + 1;
  while (leftptr <= mid && rightptr <= right) {
    if (tmp[leftptr] <= tmp[rightptr]) {
      a[aptr] = tmp[leftptr];
      aptr++;
      leftptr++;
    } else {
      a[aptr] = tmp[rightptr];
      aptr++;
      rightptr++;
      total_inversions[level] += (mid + 1 - leftptr);
    }
  }
  while (leftptr <= mid) {
    a[aptr] = tmp[leftptr];
    aptr++;
    leftptr++;
  }
  while (rightptr <= right) {
    a[aptr] = tmp[rightptr];
    aptr++;
    rightptr++;
  }
}
int main() {
  int n;
  scanf("%d", &n);
  int len = (1 << n);
  vector<int> a(len);
  for (int i = 0; i < len; i++) {
    scanf("%d", &a[i]);
  }
  vector<long long int> total_inversions(n + 1, 0);
  vector<int> a_reversed = a;
  reverse(a_reversed.begin(), a_reversed.end());
  vector<long long int> total_inversions_reversed(n + 1, 0);
  vector<long long int> total(n + 1);
  vector<int> tmp(len);
  merge_sort_count_inversion(a, 0, len - 1, n, total_inversions, tmp);
  merge_sort_count_inversion(a_reversed, 0, len - 1, n,
                             total_inversions_reversed, tmp);
  for (int i = 0; i < n; i++) {
    total_inversions[i + 1] += total_inversions[i];
    total_inversions_reversed[i + 1] += total_inversions_reversed[i];
  }
  for (int i = 0; i <= n; i++) {
    total[i] = total_inversions[i] + total_inversions_reversed[i];
  }
  int queries;
  scanf("%d", &queries);
  for (int i = 0; i < queries; i++) {
    int q;
    scanf("%d", &q);
    for (int i = q - 1; i >= 0; i--) {
      total_inversions[i] = total[i] - total_inversions[i];
    }
    long long int inv_change = total[q] - 2 * total_inversions[q];
    for (int i = n; i >= q; i--) {
      total_inversions[i] += inv_change;
    }
    printf("%I64d\n", total_inversions[n]);
  }
  return 0;
}

