    --a;
    --b;
    edges[a].push_back(b);
    edges[b].push_back(a);
    if (a > b) swap(a, b);
    memo.emplace_back(a, b);
  }
  for (int i = 0; i < (n); ++i) {
    for (auto &j : (edges[i])) {
      if (d[i] == d[j]) {
        draw_color(i);
      }
    }
  }
  vector<pair<int, int>> order;
  for (int i = 0; i < (n); ++i) {
    order.emplace_back(d[i], i);
  }
  map<pair<int, int>, ll> ans;
  sort((order).begin(), (order).end());
  for (auto &now : (order)) {
    int place = now.second;
    int dis = now.first;
    int rescolor = -1;
    for (auto &edge : (edges[place])) {
      if (d[edge] > dis) continue;
      if (d[edge] == dis) {
        if (color[edge] >= 0) {
          color[place] = !color[edge];
          int a = place;
          int b = edge;
          if (a > b) swap(a, b);
          ans[pair<int, int>(a, b)] = dis;
        }
        continue;
      }
      {
        int a = place;
        int b = edge;
        if (a > b) swap(a, b);
        ans[pair<int, int>(a, b)] = dis - d[edge];
        rescolor = color[edge];
      }
    }
    if (color[place] == -1) color[place] = rescolor;
  }
  bool flag = false;
  for (auto &i : (color)) {
    if (i) {
      flag = true;
      break;
    }
  }
  if (!flag) {
    cout << -1 << endl;
    return 0;
  }
  for (auto &i : (color)) {
    if (i) {
      cout << "W";
    } else {
      cout << "B";
    }
  }
  cout << endl;
  for (auto &i : (memo)) {
    cout << ans[i] << endl;
  }
  return 0;
}

