    for (int _ = 0; _ < 2; swap(x, y), _++) {
      int to = x;
      for (int i = 0; i < SQRT; i++) to = p[to];
      for (int i = 0; i < SQRT; i++) {
        block[x] = to;
        x = inv[x];
        to = inv[to];
      }
    }
  };
  auto query = [&](int i, int k) {
    for (; k >= SQRT; k -= SQRT) i = block[i];
    for (; k > 0; k--) i = p[i];
    return i + 1;
  };
