#include <bits/stdc++.h>
using namespace std;
using uint = unsigned int;
using ll = long long;
using ull = unsigned long long;
constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n - 1); }
template <class T>
using V = vector<T>;
template <class T>
using VV = V<V<T>>;
using P = pair<ll, ll>;
P mergema(P a, P b) {
  if (a.first > b.first) return a;
  if (a.first < b.first) return b;
  a.second += b.second;
  return a;
}
P mergemi(P a, P b) {
  if (a.first < b.first) return a;
  if (a.first > b.first) return b;
  a.second += b.second;
  return a;
}
struct Node {
  using NP = Node*;
  int sz;
  NP l, r;
  P mi, ma;
  ll lz;
  void update() {
    mi = mergemi(l->mi, r->mi);
    ma = mergema(l->ma, r->ma);
  }
  void push() {
    if (lz == 0) return;
    l->lzdata(lz);
    r->lzdata(lz);
    lz = 0;
  }
  void lzdata(ll x) {
    lz += x;
    mi.first += x;
    ma.first += x;
  }
  Node(int sz, ll fi[]) : sz(sz) {
    lz = 0;
    if (sz == 1) {
      mi = ma = P(fi[0], 1);
      return;
    }
    l = new Node(sz / 2, fi);
    r = new Node(sz - sz / 2, fi + sz / 2);
    update();
  }
  void add(int a, int b, ll x) {
    if (b <= 0 || sz <= a) return;
    if (a <= 0 && sz <= b) {
      lzdata(x);
      return;
    }
    push();
    l->add(a, b, x);
    r->add(a - sz / 2, b - sz / 2, x);
    update();
  }
  P getma(int a, int b) {
    if (b <= 0 || sz <= a) return P(-TEN(18), 0);
    if (a <= 0 && sz <= b) {
      return ma;
    }
    push();
    P pl = l->getma(a, b);
    P pr = r->getma(a - sz / 2, b - sz / 2);
    return mergema(pl, pr);
  }
  P getmi(int a, int b) {
    if (b <= 0 || sz <= a) return P(TEN(18), 0);
    if (a <= 0 && sz <= b) {
      return mi;
    }
    push();
    P pl = l->getmi(a, b);
    P pr = r->getmi(a - sz / 2, b - sz / 2);
    return mergemi(pl, pr);
  }
};
