      P pama = tra->getma(a, b);
      P pbma = trb->getma(c, d);
      P ans = P(-TEN(18), 0);
      for (int f = 0; f <= 1; f++) {
        if (f && pami.first == pama.first) continue;
        P pa = (!f) ? pami : pama;
        for (int g = 0; g <= 1; g++) {
          if (g && pbmi.first == pbma.first) continue;
          P pb = (!g) ? pbmi : pbma;
          ans = mergema(ans, P(pa.first * pb.first, pa.second * pb.second));
        }
      }
      cout << ans.first << " " << ans.second << endl;
    }
  }
  return 0;
}

