import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.math.BigInteger;
import java.util.StringTokenizer;

public class PartialSums {
    public static void main(String[] args) {
        InputReader r = new InputReader(System.in);
        int n = r.nextInt();
        int k = r.nextInt();
        long mod = (long) 1e9 + 7;
        long[] arr = new long[n];
        arr[0] = k % mod;
        for (int i = 1; i < n; i++) {
            arr[i] = arr[i - 1] * (k + i);
            arr[i] %= mod;
            arr[i] *= new Integer((BigInteger.valueOf(i +1).modInverse(BigInteger.valueOf(mod))).toString());
            arr[i] %= mod;
        }
//      for(long x:arr)System.out.println(x);
//      System.out.println("--");
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = r.nextLong();
        long[] res = new long[n];
        for (int i = 0; i < res.length; i++) {
            res[i] = a[i] % mod;
            int in=0;
            for (int j = i - 1; j >= 0; j--) {
                res[i] += a[j] * arr[in++];
                res[i] %= mod;
            }
        }
        for (long x : res)
            System.out.print(x+" ");
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                // TODO Auto-generated catch block
                e.printStackTrace();
                return null;
            }
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
vector<vector<pair<int, int> > > G, rG;
vector<vector<int> > I, rI;
long long C[100100], rC[100100];
bool tmp[100100];
bool bridge[100100];
int lst[100100][3];
void shortest(vector<vector<pair<int, int> > > g, long long *c, int s) {
  for (int i = 0; i < 100100; i++) {
    c[i] = 1e15;
  }
  c[s] = 0;
  priority_queue<pair<long long, int> > q;
  q.push(pair<long long, int>(0, s));
  while (q.size()) {
    pair<long long, int> a = q.top();
    q.pop();
    if (c[a.second] < -a.first) continue;
    for (int i = 0; i < g[a.second].size(); i++) {
      int v = g[a.second][i].first;
      long long t = -a.first + g[a.second][i].second;
      if (c[v] > t) {
        c[v] = t;
        q.push(pair<long long, int>(-t, v));
      }
    }
  }
}
void mkbridge() {
  long long sp = C[1];
  priority_queue<pair<long long, int> > q;
  q.push(pair<long long, int>(0, 0));
  while (q.size()) {
    pair<long long, int> a = q.top();
    q.pop();
    if (tmp[a.second]) continue;
    tmp[a.second] = true;
    int id = -1;
    for (int i = 0; i < G[a.second].size(); i++) {
      int v = G[a.second][i].first;
      if (sp == C[a.second] + G[a.second][i].second + rC[v]) {
        q.push(pair<long long, int>(-C[v], v));
        id = I[a.second][i];
      }
    }
    if (q.size() == 1 && id >= 0) {
      bridge[id] = true;
    }
  }
}
int main() {
  int n, m;
  cin >> n >> m;
  G.resize(n);
  rG.resize(n);
  I.resize(n);
  rI.resize(n);
  for (int i = 0; i < m; i++) {
    int a, b, c;
    cin >> a >> b >> c;
    a--;
    b--;
    G[a].push_back(pair<int, int>(b, c));
    rG[b].push_back(pair<int, int>(a, c));
    I[a].push_back(i);
    rI[b].push_back(i);
    lst[i][0] = a;
    lst[i][1] = b;
    lst[i][2] = c;
  }
  shortest(G, C, 0);
  shortest(rG, rC, 1);
  mkbridge();
  long long sp = C[1];
  for (int i = 0; i < m; i++) {
    int a, b, c;
    a = lst[i][0];
    b = lst[i][1];
    c = lst[i][2];
    if (C[b] + c + rC[a] < sp) {
      cout << "HAPPY" << endl;
    } else if (bridge[i] && C[b] + c + rC[a] > sp && sp != (long long)(1e15)) {
      cout << "SAD" << endl;
    } else {
      cout << "SOSO" << endl;
    }
  }
}

