using namespace std;
typedef long long ll;
const ll INF = 1LL << 60;
int N, K;
ll dist[20][20];
ll f(int visited, int pos) {
	if (visited == (1 << (2 * K)) - 1) {
		return 0;
	}
	ll r = INF;
	for (int i = 0; i < K; ++i) {
		if (((visited >> i) & 1) == 0) {
			r = min(r, f(visited | (1 << i), i) + dist[pos][i]);
		} else if (((visited >> (K + i)) & 1) == 0) {
			r = min(r, f(visited | (1 << (K + i)), K + i) + dist[pos][K + i]);
		}
	}
	return r;
}
vector<vector<pair<int, int>>> G;
int main() {
	int M, P;
	cin >> N >> M >> K >> P;
	--P;
	G.resize(N);
	for (int i = 0; i < M; ++i) {
		int x, y, w;
		cin >> x >> y >> w;
		--x; --y;
		G[x].push_back({y, w});
		G[y].push_back({x, w});
	}
	vector<int> a(2 * K + 1);
	a[2 * K] = P;
	for (int i = 0; i < K; ++i) {
		int s, t;
		cin >> s >> t;
		--s; --t;
		a[i] = s;
		a[i + K] = t;
	}
	for (int i = 0; i < 2 * K; ++i) {
		vector<ll> D(N, INF);
		priority_queue<pair<ll, int>> Q;
		D[a[i]] = 0;
		Q.push({0, a[i]});
		while (!Q.empty()) {
			ll d = -Q.top().first;
			int v = Q.top().second;
			Q.pop();
			if (d != D[v]) continue;
			for (auto p : G[v]) {
				int vv = p.first;
				ll dd = d + p.second;
				if (dd < D[vv]) {
					D[vv] = dd;
					Q.push({-dd, vv});
				}
			}
		}
		for (int j = i + 1; j <= 2 * K; ++j) {
			if (D[a[j]] == INF) {
				cout << "Cannot deliver" << endl;
				return 0;
			}
			dist[i][j] = dist[j][i] = D[a[j]];
		}
	}
	cout << f(0, 2 * K) << endl;
}

#include <bits/stdc++.h>
using namespace std;
template <typename T>
T abs(T a) {
  return a < 0 ? -a : a;
}
template <typename T>
T sqr(T a) {
  return a * a;
}
const int INF = (int)1e9;
const long double EPS = 1e-9;
const long double PI = 3.1415926535897932384626433832795;
const int N = 2010;
int n, m;
vector<pair<int, int> > vs, hs;
vector<int> ys;
int tr[N];
void update(int pos, int add) {
  for (; pos < int((ys).size()); pos = (pos | (pos + 1))) tr[pos] += add;
}
int getSum(int pos) {
  int sum = 0;
  for (; pos >= 0; pos = (pos & (pos + 1)) - 1) sum += tr[pos];
  return sum;
}
inline int getSum(int lf, int rg) { return getSum(rg) - getSum(lf - 1); }
inline bool intersect(const pair<int, pair<int, int> >& v,
                      const pair<int, pair<int, int> >& h) {
  return h.second.first <= v.first && v.first <= h.second.second &&
         v.second.first <= h.first && h.first <= v.second.second;
}
vector<pair<int, pair<int, int> > > chs, cvs;
vector<pair<int, int> > es;
inline bool check(int t) {
  chs.clear();
  cvs.clear();
  for (int i = 0; i < int((vs).size());) {
    int j = i + 1;
    int lf = vs[i].second - 2 * t;
    int rg = vs[i].second + 2 * t;
    while (j < int((vs).size()) && vs[j].first == vs[i].first &&
           vs[j].second - 2 * t <= rg) {
      rg = max(rg, vs[j].second + 2 * t);
      ++j;
    }
    cvs.push_back(make_pair(vs[i].first, pair<int, int>(lf, rg)));
    i = j;
  }
  for (int i = 0; i < int((hs).size());) {
    int j = i + 1;
    int lf = hs[i].first - 2 * t;
    int rg = hs[i].first + 2 * t;
    while (j < int((hs).size()) && hs[j].second == hs[i].second &&
           hs[j].first - 2 * t <= rg) {
      rg = max(rg, hs[j].first + 2 * t);
      ++j;
    }
    chs.push_back(make_pair(hs[i].second, pair<int, int>(lf, rg)));
    i = j;
  }
  for (int i = 0; i < int(int((cvs).size())); ++i) {
    es.clear();
    memset(tr, 0, sizeof(int) * int((ys).size()));
    for (int j = 0; j < int(int((chs).size())); ++j) {
      if (intersect(cvs[i], chs[j])) {
        update(chs[j].first, 1);
        es.push_back(pair<int, int>(chs[j].second.second, chs[j].first));
      }
    }
    sort((es).begin(), (es).end());
    int pe = 0;
    for (int j = i + 1; j < int((cvs).size()); ++j) {
      while (pe < int((es).size()) && es[pe].first < cvs[j].first) {
        update(es[pe].second, -1);
        pe++;
      }
      if (pe + 1 >= int((es).size())) break;
      int lf = max(cvs[i].second.first, cvs[j].second.first),
          rg = min(cvs[i].second.second, cvs[j].second.second);
      lf = lower_bound((ys).begin(), (ys).end(), lf) - ys.begin();
      rg = upper_bound((ys).begin(), (ys).end(), rg) - ys.begin();
      rg--;
      if (lf <= rg && getSum(lf, rg) >= 2) return true;
    }
  }
  return false;
}
int main() {
  cin >> n >> m;
  for (int i = 0; i < int(n); ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    vs.push_back(pair<int, int>(x + y, x - y));
  }
  for (int i = 0; i < int(m); ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    hs.push_back(pair<int, int>(x + y, x - y));
    ys.push_back(x - y);
  }
  sort((vs).begin(), (vs).end());
  sort((hs).begin(), (hs).end());
  for (int i = 0; i < int(int((hs).size())); ++i) {
    hs[i].second =
        lower_bound((ys).begin(), (ys).end(), hs[i].second) - ys.begin();
  }
  cvs.reserve(int((vs).size()));
  chs.reserve(int((hs).size()));
  es.reserve(int((hs).size()));
  sort((ys).begin(), (ys).end());
  ys.erase(unique((ys).begin(), (ys).end()), ys.end());
  int lf = 0, rg = 10000000;
  while (rg - lf > 1) {
    int mid = (lf + rg) >> 1;
    if (check(mid))
      rg = mid;
    else
      lf = mid;
  }
  if (check(rg))
    cout << rg << endl;
  else
    puts("Poor Sereja!");
  return 0;
}
